/*
 * Like printf, only we append to a buffer.
 */
protected int
file_vprintf(struct magic_set *ms, const char *fmt, va_list ap)
{
        int len;
        char *buf, *newstr;

        if (ms->event_flags & EVENT_HAD_ERR)
                return 0;
        len = vasprintf(&buf, fmt, ap);
        if (len < 0)
                goto out;

        if (ms->o.buf != NULL) {
                len = asprintf(&newstr, "%s%s", ms->o.buf, buf);
                free(buf);
                if (len < 0)
                        goto out;
                free(ms->o.buf);
                buf = newstr;
        }
        ms->o.buf = buf;
        return 0;
out:
        fprintf(stderr, "vasprintf failed (%s)", strerror(errno));
        return -1;
}

protected int
file_printf(struct magic_set *ms, const char *fmt, ...)
{
        int rv;
        va_list ap;

        va_start(ap, fmt);
        rv = file_vprintf(ms, fmt, ap);
        va_end(ap);
        return rv;
}

/*
 * error - print best error message possible
 */
/*VARARGS*/
__attribute__((__format__(__printf__, 3, 0)))
private void
file_error_core(struct magic_set *ms, int error, const char *f, va_list va,
    size_t lineno)
{
        /* Only the first error is ok */
        if (ms->event_flags & EVENT_HAD_ERR)
                return;
        if (lineno != 0) {
                free(ms->o.buf);
                ms->o.buf = NULL;
                file_printf(ms, "line %" SIZE_T_FORMAT "u:", lineno);
        }
        if (ms->o.buf && *ms->o.buf)
                file_printf(ms, " ");
        file_vprintf(ms, f, va);
        if (error > 0)
                file_printf(ms, " (%s)", strerror(error));
        ms->event_flags |= EVENT_HAD_ERR;
        ms->error = error;
}

/*VARARGS*/
protected void
file_error(struct magic_set *ms, int error, const char *f, ...)
{
        va_list va;
        va_start(va, f);
        file_error_core(ms, error, f, va, 0);
        va_end(va);
}

/*
 * Print an error with magic line number.
 */
/*VARARGS*/
protected void
file_magerror(struct magic_set *ms, const char *f, ...)
{
        va_list va;
        va_start(va, f);
        file_error_core(ms, 0, f, va, ms->line);
        va_end(va);
}

protected void
file_oomem(struct magic_set *ms, size_t len)
{
        file_error(ms, errno, "cannot allocate %" SIZE_T_FORMAT "u bytes",
            len);
}

protected void
file_badseek(struct magic_set *ms)
{
        file_error(ms, errno, "error seeking");
}

protected void
file_badread(struct magic_set *ms)
{
        file_error(ms, errno, "error reading");
}

#ifndef COMPILE_ONLY

static int
checkdone(struct magic_set *ms, int *rv)
{
        if ((ms->flags & MAGIC_CONTINUE) == 0)
                return 1;
        if (file_printf(ms, "\n- ") == -1)
                *rv = -1;
        return 0;
}

/*ARGSUSED*/
protected int
file_buffer(struct magic_set *ms, int fd, const char *inname __attribute__ ((__unused__)),
    const void *buf, size_t nb)
{
        int m = 0, rv = 0, looks_text = 0;
        const unsigned char *ubuf = CAST(const unsigned char *, buf);
        unichar *u8buf = NULL;
        size_t ulen;
        const char *code = NULL;
        const char *code_mime = "binary";
        const char *type = "application/octet-stream";
        const char *def = "data";
        const char *ftype = NULL;

        if (nb == 0) {
                def = "empty";
                type = "application/x-empty";
                goto simple;
        } else if (nb == 1) {
                def = "very short file (no magic)";
                goto simple;
        }

        if ((ms->flags & MAGIC_NO_CHECK_ENCODING) == 0) {
                looks_text = file_encoding(ms, ubuf, nb, &u8buf, &ulen,
                    &code, &code_mime, &ftype);
        }

#ifdef __EMX__
        if ((ms->flags & MAGIC_NO_CHECK_APPTYPE) == 0 && inname) {
                m = file_os2_apptype(ms, inname, buf, nb);
                if ((ms->flags & MAGIC_DEBUG) != 0)
                        (void)fprintf(stderr, "[try os2_apptype %d]\n", m);
                switch (m) {
                case -1:
                        return -1;
                case 0:
                        break;
                default:
                        return 1;
                }
        }
#endif
